function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MagicDictionary' || args[0].length !== 0) return 'Start with MagicDictionary and no arguments.';
  if (operations[1] !== 'buildDict' || args[1].length !== 1 || !Array.isArray(args[1][0])) return 'The second call must be buildDict with a list of words.';
  const word = (w) => typeof w === 'string' && w.length >= 1 && w.length <= 100 && /^[a-z]+$/.test(w);
  const dictionary = args[1][0];
  if (dictionary.length < 1 || dictionary.length > 100) return 'dictionary holds 1 to 100 words.';
  if (!dictionary.every(word)) return 'Each word has 1 to 100 lowercase letters.';
  if (new Set(dictionary).size !== dictionary.length) return 'The words in dictionary must be distinct.';
  if (operations.length - 2 > 100) return 'At most 100 calls to search.';
  for (let i = 2; i < operations.length; i++) {
    if (operations[i] !== 'search') return 'After buildDict only search can be called.';
    if (args[i].length !== 1 || !word(args[i][0])) return 'search takes one word of 1 to 100 lowercase letters.';
  }
  return null;
}

