class MagicDictionary {
  constructor() {
    this.words = new Set();
    this.patterns = new Map();
  }

  buildDict(dictionary) {
    for (const word of dictionary) {
      this.words.add(word);
      for (let i = 0; i < word.length; i++) {
        const pattern = word.slice(0, i) + '*' + word.slice(i + 1);
        this.patterns.set(pattern, (this.patterns.get(pattern) || 0) + 1);
      }
    }
  }

  search(searchWord) {
    for (let i = 0; i < searchWord.length; i++) {
      const pattern = searchWord.slice(0, i) + '*' + searchWord.slice(i + 1);
      const count = this.patterns.get(pattern) || 0;
      if (count > 1 || (count === 1 && !this.words.has(searchWord))) {
        return true;
      }
    }
    return false;
  }
}

