class MagicDictionary {
  constructor() {
    this.stored = [];
  }
  buildDict(dictionary) {
    this.stored = dictionary.slice();
  }
  search(searchWord) {
    return this.stored.some(word => {
      if (word.length !== searchWord.length) return false;
      let differences = 0;
      for (let i = 0; i < word.length; i++) if (word[i] !== searchWord[i]) differences++;
      return differences === 1;
    });
  }
}

