function generate(rand, size) {
  const large = size === 'large';
  const alphabet = large ? (rand() < 0.5 ? 'ab' : 'abcdefghijklmnopqrstuvwxyz') : (rand() < 0.6 ? 'ab' : 'abc');
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const minLength = large ? 60 : 1;
  const maxLength = large ? 100 : 4;
  const randomWord = () => {
    const length = minLength + Math.floor(rand() * (maxLength - minLength + 1));
    let word = '';
    for (let i = 0; i < length; i++) word += letter();
    return word;
  };
  const wanted = large ? 100 : 1 + Math.floor(rand() * 6);
  const words = new Set();
  for (let tries = 0; words.size < wanted && tries < 200; tries++) words.add(randomWord());
  const dictionary = [...words];
  const change = (word, times) => {
    const chars = word.split('');
    for (let t = 0; t < times; t++) {
      const i = Math.floor(rand() * chars.length);
      let next = letter();
      while (next === chars[i]) next = letter();
      chars[i] = next;
    }
    return chars.join('');
  };
  const operations = ['MagicDictionary', 'buildDict'];
  const args = [[], [dictionary]];
  const searches = large ? 100 : Math.floor(rand() * 8);
  for (let s = 0; s < searches; s++) {
    const base = dictionary[Math.floor(rand() * dictionary.length)];
    const r = rand();
    let query;
    if (r < 0.2) query = base;
    else if (r < 0.6) query = change(base, 1);
    else if (r < 0.8) query = change(base, 2);
    else query = randomWord();
    operations.push('search');
    args.push([query]);
  }
  return [operations, args];
}
